raw['post']=head(X['post']['h1'])+'<p class="meta">'+html.escape(X['post']['meta'])+'</p><nav class="toc" aria-label="Содержание">'+X['post']['toc']+'</nav><article class="content">'+X['post']['body']+'</article>'+X['post']['sequence']+X['post']['related']+'<h2>Темы статьи</h2>'+X['post']['tags']
raw['blog']=head('Блог','Статьи про вайбкодинг, Claude Code и AI-инструменты')+'<label class="visually-hidden" for="search">Поиск по статьям</label><input id="search" class="search" type="search" placeholder="Поиск по статьям" autocomplete="off"><p id="result-count" class="meta" role="status" aria-live="polite"></p><button id="reset" class="text-btn" hidden>Сбросить поиск и подборку</button><div id="browse">'+X['blog']['blog']+'</div><p id="empty" hidden>Статей по этому запросу пока нет. Попробуйте другое слово или сбросьте поиск.</p><p><a href="https://t.me/sereja_tech">Подписаться на новые статьи</a></p>'
raw['about']=X['about']['prose'];raw['links']=X['links']['prose']
raw['tags']=B['tags']['html'];raw['topic']=B['topic']['html'];raw['error']=head('Страница не найдена','Возможно, в адресе опечатка или страница переехала.')+'<p class="meta">Ошибка 404</p><nav class="toc"><ul><li><a href="after-home.html">На главную</a></li><li><a href="after-blog.html">Найти статью в блоге</a></li></ul></nav>'
raw['rich']=head(X['rich']['h1'],'Пересказ анонса Anthropic и 22 отзыва партнёров, разложенные по типу использования модели.')+'<nav class="toc"><ul><li><a href="#model">Claude Fable 5.1</a></li><li><a href="#usilie">Бенчмарки по уровням усилия</a></li><li><a href="#prompting">Как промптить Fable 5.1</a></li></ul></nav>'+X['rich']['richModel']+X['rich']['richSection']+X['rich']['richPrompt']
with sync_playwright() as p:
 b=p.chromium.launch();page=b.new_page()
 for key,body in raw.items():
  cleaned=page.evaluate(r'''({key,body})=>{const d=new DOMParser().parseFromString(body,'text/html');d.querySelectorAll('script,.kicker,.theme-btn').forEach(e=>e.remove());d.querySelectorAll('style').forEach(e=>{if(!e.closest('svg'))e.remove()});d.querySelectorAll('[onclick]').forEach(e=>e.removeAttribute('onclick'));d.querySelectorAll('.heading-anchor').forEach(e=>e.textContent='§');d.querySelectorAll('a.is-active').forEach(e=>{e.classList.remove('is-active');e.removeAttribute('aria-current')});d.querySelectorAll('.posts a,.tags a').forEach(e=>{e.textContent=e.textContent.replace(/\s*\((\d+)\)/g,' · $1')});d.querySelectorAll('h1,h2,h3').forEach(e=>e.removeAttribute('class'));d.querySelectorAll('.crumb').forEach(e=>e.innerHTML='<a href="after-blog.html">← Блог</a>');
  if(key==='blog'){d.querySelector('#browse>nav>p').outerHTML='<h2 style="margin-top:10px">Что хотите сделать?</h2>';d.querySelector('#browse>nav').className='topics';d.querySelectorAll('[data-topic]').forEach(e=>e.className='topic-link');d.querySelectorAll('#browse>h2').forEach(e=>e.className='month-head')}
  if(key==='home'){const v=[...d.querySelectorAll('section')].find(e=>e.querySelector('h2')?.textContent==='Видео');v.className='home-video';v.querySelector('h2').insertAdjacentHTML('afterend','<div class="video-frame"><iframe src="https://www.youtube-nocookie.com/embed/SAZQy5JK9tM" title="Grok 4.6 vs DeepSeek V4 Pro — игры, код и агенты" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>');d.querySelector('.masthead').after(v)}
  if(key==='post'){const first=d.querySelector('.content>p');first.className='lede';d.querySelector('.masthead').append(first);const meta=d.querySelector('.meta');d.querySelector('.masthead').append(meta);const cover=d.createElement('figure');cover.innerHTML='<img class="post-cover" src="/images/blog/best-practices-code-ledger.webp" alt="Почему агент не может выбрать лучший код"><figcaption>Почему агент не может выбрать лучший код</figcaption>';cover.className='post-hero';cover.querySelector('figcaption').remove();d.querySelector('.masthead').prepend(cover)}
  d.querySelectorAll('table').forEach(t=>{const heads=[...t.querySelectorAll('thead th')].map(e=>e.textContent.trim());const list=d.createElement('ul');list.className='value-list';for(const tr of t.querySelectorAll('tbody tr')){const cells=[...tr.children];const li=d.createElement('li');li.innerHTML='<strong>'+cells[0].innerHTML+'.</strong> '+cells.slice(1).map((c,i)=>(heads[i+1]?heads[i+1]+': ':'')+c.innerHTML).join('. ');list.append(li)}t.replaceWith(list)});
  const prompt=(title,text)=>{const w=d.createElement('div');w.className='prompt-wrap';w.innerHTML='<details class="prompt-card"><summary><span class="prompt-name"></span><span class="toggle">Развернуть [+]</span><button type="button" class="copy">Скопировать</button></summary><pre class="prompt-body"><code></code></pre></details><p class="prompt-src">Источник: авторский промпт из текущей статьи на sereja.tech; текст сохранён.</p>';w.querySelector('.prompt-name').textContent=title;w.querySelector('code').textContent=text;return w};
  d.querySelectorAll('.callout.prompt').forEach(e=>e.replaceWith(prompt(e.querySelector('strong').textContent,[...e.querySelectorAll('.callout-body p')].map(p=>p.textContent).join('\n\n'))));
  if(key==='rich'){const sec=d.querySelector('#usilie'),cards=[...sec.querySelectorAll('.card')].slice(0,3);const intro=sec.querySelector('.page');sec.innerHTML=intro.innerHTML;sec.querySelector('p').textContent='Графики из анонса показывают качество и цену на разных уровнях усилия. По ним можно сопоставить стоимость задачи с полученным результатом.';const gallery=d.createElement('div');gallery.className='chart-gallery';gallery.tabIndex=0;gallery.innerHTML='<div class="chart-controls"><button id="prev-chart" aria-label="Предыдущий график">← Назад</button><span id="chart-count"></span><button id="next-chart" aria-label="Следующий график">Дальше →</button></div>';cards.forEach(c=>{c.className='chart-slide';c.querySelectorAll('[style]').forEach(e=>e.removeAttribute('style'));gallery.append(c)});sec.append(gallery);const mod=d.querySelector('#model');mod.removeAttribute('style');mod.insertAdjacentHTML('afterbegin','<h2>Claude Fable 5.1</h2>');const ps=d.querySelector('#prompting');const cp=ps.querySelector('pre');const txt=cp?.textContent||'Сформулируй цель, ограничения и способ проверки результата.';ps.innerHTML='<h2>Как промптить Fable 5.1</h2><p>Между вызовами инструментов агент может молчать, а в итоге сообщить только о последнем шаге. Попросите его коротко объяснять, что он делает и что проверил.</p>';const pr=prompt('Прогресс работы агента',txt);pr.querySelector('.prompt-src').textContent='Источник: промпт из раздела «Как промптить Fable 5.1» текущей статьи.';ps.append(pr)}
  d.querySelectorAll('a[href]').forEach(e=>{const href=e.getAttribute('href');if(href.startsWith('#')||href.startsWith('?')||href.startsWith('after-'))return;const mapping={'/':'home','/blog/':'blog','/about/':'about','/links/':'links','/tags/':'tags','/tags/claude-code/':'topic','/blog/best-practices-code/':'post','/blog/claude-fable-5-1/':'rich'};let path=href.startsWith('https://sereja.tech')?href.slice(19):href;if(mapping[path])e.setAttribute('href','after-'+mapping[path]+'.html');else if(href.startsWith('/'))e.setAttribute('href','https://sereja.tech'+href)});
  d.querySelectorAll('img[src^="/"]').forEach(e=>e.src='https://sereja.tech'+e.getAttribute('src'));return d.body.innerHTML}''',{'key':key,'body':body})
  (R/f'after-{key}.html').write_text(wrap(B[key]['h1'],cleaned))
 b.close()
